create table if not exists organizations(id uuid primary key default gen_random_uuid(),owner_user_id uuid not null references profiles(id) on delete restrict,name text not null,legal_name text,base_currency text not null references currencies(code) default 'SAR',entity_type text not null default 'FAMILY',status text not null default 'ACTIVE',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists organization_members(organization_id uuid not null references organizations(id) on delete cascade,user_id uuid not null references profiles(id) on delete cascade,role text not null check(role in ('OWNER','ADMIN','ACCOUNTANT','ADVISOR','VIEWER','SHARIA_REVIEWER')),status text not null default 'ACTIVE',created_at timestamptz not null default now(),primary key(organization_id,user_id));
create table if not exists organization_entities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,name text not null,entity_type text not null default 'PERSON',registration_no text,base_currency text not null references currencies(code) default 'SAR',zakat_method_id uuid references zakat_methods(id),nisab_standard text not null default 'SILVER',active boolean not null default true,metadata jsonb not null default '{}',created_at timestamptz not null default now());
alter table asset_accounts add column if not exists organization_id uuid references organizations(id) on delete cascade; alter table asset_accounts add column if not exists entity_id uuid references organization_entities(id) on delete set null;
alter table transactions add column if not exists organization_id uuid references organizations(id) on delete cascade; alter table transactions add column if not exists entity_id uuid references organization_entities(id) on delete set null;
alter table lots add column if not exists organization_id uuid references organizations(id) on delete cascade;
alter table zakat_assessments add column if not exists organization_id uuid references organizations(id) on delete cascade; alter table zakat_assessments add column if not exists entity_id uuid references organization_entities(id) on delete set null;
create table if not exists consolidated_assessments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,assessment_date date not null,valuation_date date not null,currency text not null references currencies(code),total_entity_value numeric(24,8) not null default 0,total_zakat_due numeric(24,8) not null default 0,status text not null default 'DRAFT',snapshot jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists organization_invitations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,email text not null,role text not null,token text unique not null default encode(gen_random_bytes(24),'hex'),expires_at timestamptz not null default now()+interval '7 days',accepted_at timestamptz,created_at timestamptz not null default now());
create index if not exists idx_org_members_user on organization_members(user_id); create index if not exists idx_org_entities_org on organization_entities(organization_id); create index if not exists idx_org_assets on asset_accounts(organization_id); create index if not exists idx_org_assessments on zakat_assessments(organization_id);
alter table organizations enable row level security; alter table organization_members enable row level security; alter table organization_entities enable row level security; alter table consolidated_assessments enable row level security; alter table organization_invitations enable row level security;
create policy org_membership_read on organizations for select using(owner_user_id=auth.uid() or exists(select 1 from organization_members m where m.organization_id=id and m.user_id=auth.uid()));
create policy org_owner_write on organizations for all using(owner_user_id=auth.uid()) with check(owner_user_id=auth.uid());
create policy org_member_read on organization_members for select using(user_id=auth.uid() or exists(select 1 from organization_members m where m.organization_id=organization_members.organization_id and m.user_id=auth.uid() and m.role in ('OWNER','ADMIN')));
create policy org_member_manage on organization_members for all using(exists(select 1 from organization_members m where m.organization_id=organization_members.organization_id and m.user_id=auth.uid() and m.role in ('OWNER','ADMIN'))) with check(exists(select 1 from organization_members m where m.organization_id=organization_members.organization_id and m.user_id=auth.uid() and m.role in ('OWNER','ADMIN')));
create policy entity_org_access on organization_entities for all using(exists(select 1 from organization_members m where m.organization_id=organization_entities.organization_id and m.user_id=auth.uid())) with check(exists(select 1 from organization_members m where m.organization_id=organization_entities.organization_id and m.user_id=auth.uid()));
create policy consolidated_org_access on consolidated_assessments for all using(exists(select 1 from organization_members m where m.organization_id=consolidated_assessments.organization_id and m.user_id=auth.uid())) with check(exists(select 1 from organization_members m where m.organization_id=consolidated_assessments.organization_id and m.user_id=auth.uid()));
create policy invitation_admin on organization_invitations for all using(exists(select 1 from organization_members m where m.organization_id=organization_invitations.organization_id and m.user_id=auth.uid() and m.role in ('OWNER','ADMIN'))) with check(exists(select 1 from organization_members m where m.organization_id=organization_invitations.organization_id and m.user_id=auth.uid() and m.role in ('OWNER','ADMIN')));
